import png_helper as ph, numpy as np
img = ph.load_png('input/A-602.png')
# Check y=180..535 and y=830..945 on A-602.png for text rows
for y1, y2 in [(180, 535), (830, 945)]:
    sub = img[y1:y2, 165:1350, :3].mean(axis=2) < 190
    # find horizontal bands of text (where row has between 5 and 800 dark pixels, not a full horizontal line > 900 px)
    row_cnts = sub.sum(axis=1)
    in_band = False
    bands = []
    for r, c in enumerate(row_cnts):
        if 5 <= c <= 900:
            if not in_band:
                bands.append([y1+r, y1+r])
                in_band = True
            else:
                bands[-1][1] = y1+r
        else:
            in_band = False
    print(f'Range {y1}..{y2} bands:', bands)
"

