import sys; sys.path.append('/tmp')
import png_helper as ph, numpy as np
img = ph.load_png('input/A-602.png')

def print_table(y1, y2):
    gray = img[y1:y2, :, :3].mean(axis=2)
    vlines = [x for x in range(160, 1370) if (gray[:, x] < 210).sum() > (y2-y1)*0.7]
    cols = []
    for v in vlines:
        if not cols or v - cols[-1][-1] > 5:
            cols.append([v])
        else:
            cols[-1].append(v)
    col_xs = [int(np.mean(c)) for c in cols]
    hlines = [y1+r for r in range(y2-y1) if (gray[r, 175:1355] < 210).sum() > 900]
