python3 -c "
import sys; sys.path.append('output')
import solution as sol, numpy as np

for svc_name, segs in [('CT-1', sol.CT_SEGMENTS), ('BW-1', sol.BW_SEGMENTS), ('CHW-1', sol.CHW_SEGMENTS)]:
    tot_len = sum(np.linalg.norm(np.array(p2) - np.array(p1)) for _, p1, p2 in segs) / 1000.0
    # Verify single connected component via BFS
    adj = {i: [] for i in range(len(segs))}
    for i, (_, p1, p2) in enumerate(segs):
        for j, (_, q1, q2) in enumerate(segs):
            if i == j: continue
            # Check if segment i and j share an endpoint or endpoint lies on segment
            for pt in (np.array(p1), np.array(p2)):
                a, b = np.array(q1), np.array(q2)
                ab = b - a
                t = np.clip(np.dot(pt - a, ab) / np.dot(ab, ab), 0.0, 1.0)
                if np.linalg.norm(pt - (a + t * ab)) < 1e-3:
                    adj[i].append(j)
    vis = {0}
    stack = [0]
    while stack:
        u = stack.pop()
        for v in adj[u]:
            if v not in vis:
                vis.add(v); stack.append(v)
    assert len(vis) == len(segs), f'{svc_name} not connected: {vis}'
    print(f'[PASS] Gate 3 ({svc_name}): 1 connected component ({len(segs)} segments, total length = {tot_len:.3f} m)')
" && ls -lh output/solution.py output/model.ifc output/reconciliation.json

